 global n
 n+=1;d=copy.copy(s.data)
 for k in range(2):
  a=a0.copy() if k==0 else a1.copy();a[:7]=np.clip(x[7*k:7*(k+1)],s.lower[:7],s.upper[:7]);d.ctrl[s._act]=a
  for _ in range(10):s.mj.mj_step(s.model,d)
 v=rcb_dtb.keypoint_distance(d.xpos[s._obj],d.xquat[s._obj],g)
 if v<best[0]:best[:]=[v,x.copy()];print('best',n,round(v,7),'time',round(time.time()-t,1),flush=True)
 return v
x0=np.r_[a0[:7],a1[:7]];simplex=np.vstack([x0]+[x0+np.eye(14)[j]*.07 for j in range(14)])
res=minimize(fun,x0,method='Nelder-Mead',options={'initial_simplex':simplex,'maxfev':3000,'xatol':1e-4,'fatol':1e-5})
